    /// <summary>Gets the left and right glyph bounds using the same Unicode and WinAnsi aliases as advance widths.</summary>
    internal static bool TryGetHorizontalBounds1000(PdfStandardFont font, char value, out int left, out int right) {
        short[]? bounds = font switch {
            PdfStandardFont.Helvetica => HelveticaHorizontalPaintBounds,
            PdfStandardFont.HelveticaOblique => HelveticaObliqueHorizontalPaintBounds,
            PdfStandardFont.HelveticaBold => HelveticaBoldHorizontalPaintBounds,
            PdfStandardFont.HelveticaBoldOblique => HelveticaBoldObliqueHorizontalPaintBounds,
            PdfStandardFont.TimesRoman => TimesRomanHorizontalPaintBounds,
            PdfStandardFont.TimesItalic => TimesItalicHorizontalPaintBounds,
            PdfStandardFont.TimesBold => TimesBoldHorizontalPaintBounds,
            PdfStandardFont.TimesBoldItalic => TimesBoldItalicHorizontalPaintBounds,
            PdfStandardFont.Courier => CourierHorizontalPaintBounds,
            PdfStandardFont.CourierOblique => CourierObliqueHorizontalPaintBounds,
            PdfStandardFont.CourierBold => CourierBoldHorizontalPaintBounds,
            PdfStandardFont.CourierBoldOblique => CourierBoldObliqueHorizontalPaintBounds,
            _ => null
        };
        left = right = 0;
        if (bounds == null) return false;
        // WinAnsiEncoding paints the space and hyphen glyphs for these characters.
        if (value == '\u00A0') value = ' ';
        else if (value == '\u00AD') value = '-';
        int index = System.Array.BinarySearch(Characters, value);
        if (index < 0) return false;
        left = bounds[index * 2];
        right = bounds[index * 2 + 1];
        // A zero box for a non-space glyph (notably Euro) has no qualified ink metadata.
        return value == ' ' || left != 0 || right != 0;
    }
